// Execution Analytics Types - Verified vs Generated

// Verified (deterministic):
// - semantic_query: from a pre-defined semantic model
// - omni_query: from a pre-defined integration (OmniQuery)
// - automation: automation defined inline in agent config
//
// Not Verified (generated by LLM):
// - sql_generated: SQL generated by LLM (sql: None)
// - agent_tool: agent tool defined as an asset/artifact in the agent

export type ExecutionType =
  | "semantic_query"
  | "omni_query"
  | "sql_generated"
  | "workflow"
  | "agent_tool";

type ExecutionCategory = "verified" | "generated";

export interface ExecutionTypeInfo {
  type: ExecutionType;
  label: string;
  shortLabel: string;
  category: ExecutionCategory;
  color: string;
  chartColor: string;
  bgColor: string;
  borderColor: string;
  description: string;
}

