export interface ExecutionSummary {
  totalExecutions: number;
  verifiedCount: number;
  generatedCount: number;
  verifiedPercent: number;
  generatedPercent: number;
  successRateVerified: number;
  successRateGenerated: number;
  mostExecutedType: string;
  // Breakdown by type
  semanticQueryCount: number;
  omniQueryCount: number;
  sqlGeneratedCount: number;
  automationCount: number;
  agentToolCount: number;
}

export interface ExecutionTimeBucket {
  timestamp: string;
  verifiedCount: number;
  generatedCount: number;
  // Optional detailed breakdown
  semanticQueryCount?: number;
  omniQueryCount?: number;
  sqlGeneratedCount?: number;
  automationCount?: number;
  agentToolCount?: number;
}

// ── Latency percentiles ───────────────────────────────────────────────────
// GET /{projectId}/execution-analytics/percentiles?days=N
interface LatencyPercentiles {
  p50Ms: number;
  p95Ms: number;
  p99Ms: number;
  /**
   * Blended error rate (% of executions failing). Optional: NOT part of the
   * three agreed endpoint contracts — the UI falls back to the summary-derived
   * error rate when the backend omits it. See report deviation note.
   */
  errorRate?: number;
}

export interface PercentileTimePoint extends LatencyPercentiles {
  date: string;
}

export interface PercentilesResponse {
  overall: LatencyPercentiles;
  series: PercentileTimePoint[];
}

// ── Latency histogram ──────────────────────────────────────────────────────
// GET /{projectId}/execution-analytics/histogram?days=N
interface HistogramBucket {
  upperMs: number;
  count: number;
}

export interface HistogramResponse {
  buckets: HistogramBucket[];
  p50Ms: number;
  p95Ms: number;
  p99Ms: number;
}

// ── Cost & tokens by model ─────────────────────────────────────────────────
// GET /{projectId}/execution-analytics/cost?days=N
interface ModelCost {
  model: string;
  calls: number;
  tokens: number;
  costUsd: number;
  p95Ms: number;
}

export interface CostResponse {
  totalCostUsd: number;
  totalTokens: number;
  byModel: ModelCost[];
}

export interface AgentExecutionStats {
  agentRef: string;
  totalExecutions: number;
  verifiedCount: number;
  generatedCount: number;
  verifiedPercent: number;
  mostExecutedType: string;
  successRate: number;
}

type SourceType = "agent" | "workflow";

export interface ExecutionDetail {
  traceId: string;
  spanId: string;
  timestamp: string;
  executionType: ExecutionType;
  isVerified: boolean;
  // Source information
  sourceType: SourceType;
  sourceRef: string;
  // Common fields
  status: "success" | "error";
  durationMs: number;
  database?: string;
  output?: string;
  error?: string;
  // Type-specific fields
  // For semantic queries
  topic?: string;
  semanticQueryParams?: string;
  generatedSql?: string;
  // For omni queries
  integration?: string;
  endpoint?: string;
  // For SQL queries (verified)
  sql?: string;
  sqlRef?: string;
  // For SQL queries (generated)
  userQuestion?: string;
  automationRef?: string;
  agentRef?: string;
  toolInput?: string;
}
